// =============================================================================
// INTRO PAGES — embedded "About" documents for the sidebar modes
// =============================================================================
//
// Each sidebar mode's introduction page, embedded as a complete standalone
// HTML document (own styles, no external references) so BOTH hosts can show
// it without serving files: the web host via an iframe srcdoc document tab,
// the VS Code host as a WebviewPanel's html. The string constants are
// GENERATED from the design source documents — edit the source pages and
// regenerate rather than hand-editing the literals.
// =============================================================================

/** The Agents introduction, as a complete standalone HTML document. */
const AGENTS_INTRO_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>RocketRide Agent — An Introduction</title>\n<style>\n  :root {\n    --bg: #f7f8fa;\n    --surface: #ffffff;\n    --ink: #1c2230;\n    --ink-soft: #4b5568;\n    --ink-faint: #8a93a6;\n    --accent: #6a3bc4;\n    --accent-soft: #efe9fb;\n    --accent-border: #d4c4f0;\n    --accent-ink: #45277e;\n    --line: #e3e7ee;\n    --code-bg: #f1f3f7;\n    --good: #1d8a4e;\n    --bad: #c24a4a;\n    --radius: 10px;\n  }\n\n  * { box-sizing: border-box; }\n\n  body {\n    margin: 0;\n    background: var(--bg);\n    color: var(--ink);\n    font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n    font-size: 16px;\n    line-height: 1.65;\n  }\n\n  .wrap {\n    max-width: 880px;\n    margin: 0 auto;\n    padding: 0 28px 96px;\n  }\n\n  /* ============================================================ */\n  /* HERO                                                          */\n  /* ============================================================ */\n\n  header.hero {\n    background: linear-gradient(160deg, #221440 0%, #35206b 55%, #4c2e9c 100%);\n    color: #f1ecfd;\n    padding: 72px 28px 64px;\n  }\n  header.hero .inner {\n    max-width: 880px;\n    margin: 0 auto;\n  }\n  header.hero .kicker {\n    text-transform: uppercase;\n    letter-spacing: 0.14em;\n    font-size: 12px;\n    font-weight: 600;\n    color: #b49ae8;\n    margin-bottom: 14px;\n  }\n  header.hero h1 {\n    margin: 0 0 18px;\n    font-size: 40px;\n    line-height: 1.15;\n    font-weight: 700;\n  }\n  header.hero p.lede {\n    margin: 0;\n    max-width: 640px;\n    font-size: 19px;\n    line-height: 1.6;\n    color: #d6c8f3;\n  }\n\n  /* ============================================================ */\n  /* TYPOGRAPHY                                                    */\n  /* ============================================================ */\n\n  h2 {\n    font-size: 26px;\n    margin: 64px 0 16px;\n    padding-top: 8px;\n    border-top: 1px solid var(--line);\n  }\n  h3 {\n    font-size: 19px;\n    margin: 32px 0 10px;\n  }\n  p { margin: 0 0 16px; color: var(--ink-soft); }\n  strong { color: var(--ink); }\n  li { color: var(--ink-soft); margin-bottom: 8px; }\n\n  code {\n    font-family: \"Cascadia Code\", Consolas, \"SF Mono\", Menlo, monospace;\n    font-size: 0.88em;\n    background: var(--code-bg);\n    border: 1px solid var(--line);\n    border-radius: 4px;\n    padding: 1px 5px;\n    color: #33415e;\n  }\n\n  pre {\n    background: #1e2433;\n    color: #d7deed;\n    border-radius: var(--radius);\n    padding: 18px 20px;\n    overflow-x: auto;\n    font-size: 13.5px;\n    line-height: 1.55;\n  }\n  pre code {\n    background: none;\n    border: none;\n    padding: 0;\n    color: inherit;\n    font-size: inherit;\n  }\n\n  /* ============================================================ */\n  /* CARDS, TABLES, CALLOUTS                                       */\n  /* ============================================================ */\n\n  .card {\n    background: var(--surface);\n    border: 1px solid var(--line);\n    border-radius: var(--radius);\n    padding: 20px 24px;\n    margin: 20px 0;\n  }\n\n  .grid2 {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 16px;\n    margin: 20px 0;\n  }\n  .grid3 {\n    display: grid;\n    grid-template-columns: 1fr 1fr 1fr;\n    gap: 16px;\n    margin: 20px 0;\n  }\n  @media (max-width: 640px) { .grid2, .grid3 { grid-template-columns: 1fr; } }\n\n  .grid2 .card, .grid3 .card { margin: 0; }\n  .card h4 {\n    margin: 0 0 8px;\n    font-size: 15px;\n    color: var(--accent);\n  }\n  .card p { margin: 0; font-size: 14.5px; }\n  .card p + p { margin-top: 8px; }\n\n  table {\n    width: 100%;\n    border-collapse: collapse;\n    margin: 20px 0;\n    background: var(--surface);\n    border: 1px solid var(--line);\n    border-radius: var(--radius);\n    overflow: hidden;\n    font-size: 14.5px;\n  }\n  th, td {\n    text-align: left;\n    padding: 10px 14px;\n    border-bottom: 1px solid var(--line);\n    vertical-align: top;\n  }\n  th {\n    background: var(--accent-soft);\n    color: var(--accent-ink);\n    font-weight: 600;\n  }\n  tr:last-child td { border-bottom: none; }\n  td { color: var(--ink-soft); }\n  .table-scroll { overflow-x: auto; }\n\n  .callout {\n    border-left: 4px solid var(--accent);\n    background: var(--accent-soft);\n    border-radius: 0 var(--radius) var(--radius) 0;\n    padding: 14px 18px;\n    margin: 20px 0;\n    font-size: 15px;\n    color: var(--accent-ink);\n  }\n  .callout strong { color: #331c60; }\n\n  /* ============================================================ */\n  /* DIAGRAMS                                                      */\n  /* ============================================================ */\n\n  .diagram {\n    background: var(--surface);\n    border: 1px solid var(--line);\n    border-radius: var(--radius);\n    padding: 28px 20px;\n    margin: 24px 0;\n    text-align: center;\n    overflow-x: auto;\n  }\n  .diagram .caption {\n    font-size: 13px;\n    color: var(--ink-faint);\n    margin-top: 14px;\n  }\n\n  .flow {\n    display: inline-flex;\n    align-items: stretch;\n    gap: 0;\n    flex-wrap: wrap;\n    justify-content: center;\n  }\n  .flow .node {\n    background: var(--accent-soft);\n    border: 1px solid var(--accent-border);\n    border-radius: 8px;\n    padding: 12px 18px;\n    min-width: 120px;\n  }\n  .flow .node .t { font-weight: 600; font-size: 15px; color: var(--accent-ink); }\n  .flow .node .s { font-size: 12.5px; color: #7d63b0; margin-top: 2px; }\n  .flow .arrow {\n    display: flex;\n    align-items: center;\n    padding: 0 10px;\n    color: var(--ink-faint);\n    font-size: 20px;\n  }\n\n  /* ============================================================ */\n  /* CHAT MOCK — a session transcript in the page's light theme    */\n  /* ============================================================ */\n\n  .chatmock {\n    max-width: 620px;\n    margin: 0 auto;\n    text-align: left;\n    font-size: 13.5px;\n  }\n  .chatmock .cm-msg {\n    border-radius: 8px;\n    padding: 10px 14px;\n    margin: 10px 0;\n    line-height: 1.5;\n  }\n  .chatmock .cm-msg.user {\n    background: var(--accent-soft);\n    border: 1px solid var(--accent-border);\n    color: var(--accent-ink);\n    margin-left: 15%;\n  }\n  .chatmock .cm-msg.agent {\n    background: #fff;\n    border: 1px solid var(--line);\n    color: var(--ink-soft);\n    margin-right: 15%;\n  }\n  .chatmock .cm-tool {\n    background: #f3f5f9;\n    border: 1px solid var(--line);\n    border-radius: 6px;\n    margin: 10px 15% 10px 0;\n    font-family: \"Cascadia Code\", Consolas, monospace;\n    font-size: 12px;\n    overflow: hidden;\n  }\n  .chatmock .cm-tool .head {\n    display: flex;\n    gap: 10px;\n    padding: 6px 12px;\n    color: var(--ink-faint);\n    border-bottom: 1px solid var(--line);\n    background: #eceff4;\n  }\n  .chatmock .cm-tool .head .ok { color: var(--good); margin-left: auto; }\n  .chatmock .cm-tool pre {\n    margin: 0;\n    background: none;\n    color: var(--ink-soft);\n    border-radius: 0;\n    padding: 8px 12px;\n    font-size: 12px;\n  }\n  .chatmock .cm-tool .add { color: var(--good); }\n  .chatmock .cm-tool .del { color: var(--bad); }\n\n  /* ============================================================ */\n  /* LIFECYCLE STEPS                                               */\n  /* ============================================================ */\n\n  .steps { counter-reset: step; margin: 24px 0; padding: 0; list-style: none; }\n  .steps li {\n    position: relative;\n    padding: 0 0 22px 52px;\n    margin: 0;\n  }\n  .steps li::before {\n    counter-increment: step;\n    content: counter(step);\n    position: absolute;\n    left: 0; top: 0;\n    width: 32px; height: 32px;\n    border-radius: 50%;\n    background: var(--accent);\n    color: #fff;\n    font-weight: 700;\n    font-size: 15px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n  .steps li::after {\n    content: \"\";\n    position: absolute;\n    left: 15px; top: 36px; bottom: 2px;\n    width: 2px;\n    background: var(--line);\n  }\n  .steps li:last-child::after { display: none; }\n  .steps li .st { font-weight: 600; color: var(--ink); display: block; margin-bottom: 2px; }\n  .steps li .sd { font-size: 14.5px; color: var(--ink-soft); }\n\n  footer {\n    margin-top: 72px;\n    padding-top: 20px;\n    border-top: 1px solid var(--line);\n    font-size: 13px;\n    color: var(--ink-faint);\n  }\n</style>\n</head>\n<body>\n\n<header class=\"hero\">\n  <div class=\"inner\">\n    <div class=\"kicker\">RocketRide Platform</div>\n    <h1>RocketRide Agent</h1>\n    <p class=\"lede\">\n      Your coding agent in the cloud. Describe what you want in plain English\n      — an app, a custom node, a pipeline, a fix, a release — and the agent\n      builds it in your workspace: creating files, wiring components, running\n      validation, and walking the result through deploy and publish, with\n      every step visible in the conversation.\n    </p>\n  </div>\n</header>\n\n<div class=\"wrap\">\n\n  <!-- ========================================================== -->\n  <!-- WHAT IS THE AGENT                                           -->\n  <!-- ========================================================== -->\n\n  <h2>What is the Agent?</h2>\n  <p>\n    The other three tabs in the sidebar — Apps, Nodes, Pipelines — list the\n    things in your workspace. The <strong>Agent</strong> tab is how you get\n    those things made without doing the engineering yourself. It is a\n    conversation with a developer that lives in the cloud, signed in as you,\n    working directly on your workspace: the same <code>./apps</code>,\n    <code>./nodes</code>, and <code>./pipelines</code> folders the other tabs\n    show.\n  </p>\n\n  <div class=\"diagram\">\n    <div class=\"flow\">\n      <div class=\"node\"><div class=\"t\">You</div><div class=\"s\">describe the goal</div></div>\n      <div class=\"arrow\">&#8594;</div>\n      <div class=\"node\"><div class=\"t\">Agent</div><div class=\"s\">plans, edits, runs</div></div>\n      <div class=\"arrow\">&#8594;</div>\n      <div class=\"node\"><div class=\"t\">Workspace</div><div class=\"s\">apps &#183; nodes &#183; pipelines</div></div>\n      <div class=\"arrow\">&#8594;</div>\n      <div class=\"node\"><div class=\"t\">Platform</div><div class=\"s\">deploy &#183; publish</div></div>\n    </div>\n    <div class=\"caption\">One loop from an idea in English to a shipped artifact — with you steering at every turn.</div>\n  </div>\n\n  <p>\n    The agent is not a form filler or a snippet generator. It reads your\n    workspace before it acts, uses the same scaffolds, validation, and\n    lifecycle verbs a human developer uses, and reports back in sentences —\n    what it found, what it changed, and what it suggests doing next.\n  </p>\n\n  <div class=\"grid2\">\n    <div class=\"card\">\n      <h4>Who it is for</h4>\n      <p>Anyone with a RocketRide cloud workspace. You do not need to know\n      the <code>.pipe</code> format, the app SDK, or the node contract —\n      you need to know what you want built. Developers use it too: it is\n      often the fastest way to scaffold, wire, and ship.</p>\n    </div>\n    <div class=\"card\">\n      <h4>Where it runs</h4>\n      <p>In the cloud, against your cloud workspace. Sessions keep working\n      after you close the tab — come back and the conversation has moved\n      on. The Agent tab is part of the cloud UI; in VS Code you work on the\n      same workspace with your own editor tooling instead.</p>\n    </div>\n  </div>\n\n  <!-- ========================================================== -->\n  <!-- WHAT YOU CAN BUILD                                          -->\n  <!-- ========================================================== -->\n\n  <h2>What you can ask for</h2>\n  <p>\n    Everything the platform can hold, the agent can build, change, and ship.\n    The three artifact kinds each have their own introduction page; the agent\n    is the hands that make them:\n  </p>\n\n  <div class=\"grid3\">\n    <div class=\"card\">\n      <h4>Apps</h4>\n      <p>\"Build me an app where my team uploads contracts and chats with\n      them.\" The agent scaffolds the app through the platform wizard, builds\n      the UI from the stock component set, embeds the pipeline, and wires\n      the preview.</p>\n    </div>\n    <div class=\"card\">\n      <h4>Pipelines</h4>\n      <p>\"Make a pipeline that ingests our support tickets into a vector\n      store.\" The agent picks components from the catalog, wires the lanes,\n      fills in profiles, and validates the graph before anything runs.</p>\n    </div>\n    <div class=\"card\">\n      <h4>Nodes</h4>\n      <p>\"I need a component that calls our internal pricing API.\" The agent\n      scaffolds a custom node, writes the handlers and manifest, and tests\n      it against sample input in a local engine run.</p>\n    </div>\n  </div>\n\n  <p>And creation is only the start of what a session can carry:</p>\n  <ul>\n    <li><strong>Modify what exists.</strong> \"Add a retry lane to\n      invoice-intake that catches parse failures.\" The agent reads the\n      current file, explains what it found, and makes the targeted change.</li>\n    <li><strong>Run and verify.</strong> Validate a pipeline, start a test\n      run against sample data, check the output, read the logs — inside the\n      same conversation.</li>\n    <li><strong>Fix things.</strong> Paste an error, point at a misbehaving\n      app, or just describe the symptom; the agent investigates in the\n      workspace and proposes the fix as a diff.</li>\n    <li><strong>Deploy and publish.</strong> \"Ship this to my team.\" The\n      agent deploys a version, publishes it to the rung you name —\n      <code>@me</code> to try it yourself, <code>@team</code> to share it,\n      <code>@public</code> to submit it to the store — and can roll it back\n      the same way.</li>\n    <li><strong>Schedule.</strong> Put a deployed pipeline on a cron window\n      (\"every weekday at 08:00\") without touching a config screen.</li>\n  </ul>\n\n  <!-- ========================================================== -->\n  <!-- WHAT A SESSION LOOKS LIKE                                   -->\n  <!-- ========================================================== -->\n\n  <h2>What a session looks like</h2>\n  <p>\n    Work happens in <strong>sessions</strong>. The Agent tab lists yours in\n    the sidebar — one per task, named for what it is doing, each opening as\n    its own document tab. A session is a conversation, but one where the\n    agent's actions are first-class: every file edit, validation, and run\n    appears inline, as it happens.\n  </p>\n\n  <div class=\"diagram\">\n    <div class=\"chatmock\">\n      <div class=\"cm-msg user\">Add a retry lane to invoice-intake that catches parse failures and reruns them through the OCR profile.</div>\n      <div class=\"cm-msg agent\">I read the pipeline. Parse failures currently drop on the error lane. I will add a retry lane routed through the ocr profile, capped at 2 attempts.</div>\n      <div class=\"cm-tool\">\n        <div class=\"head\"><span>edit</span><span>pipelines/invoice-intake.pipe</span><span class=\"ok\">applied</span></div>\n        <pre><span class=\"add\">+  \"retry\": { \"lane\": \"ocr-retry\", \"max_attempts\": 2,</span>\n<span class=\"add\">+             \"profile\": \"ocr\" },</span>\n<span class=\"del\">-  \"on_error\": \"drop\"</span></pre>\n      </div>\n      <div class=\"cm-tool\">\n        <div class=\"head\"><span>run</span><span>validate invoice-intake.pipe</span><span class=\"ok\">passed</span></div>\n        <pre>pipeline valid — 2 lanes, 6 components</pre>\n      </div>\n      <div class=\"cm-msg agent\">Validation passed. Want me to start a run against the sample batch to confirm the retry path fires?</div>\n    </div>\n    <div class=\"caption\">A session in flight: the request, the agent's read of the situation, the diff, the validation — then a question back to you.</div>\n  </div>\n\n  <h3>The anatomy of the conversation</h3>\n  <ul>\n    <li><strong>Every change is a diff.</strong> The agent edits your\n      workspace files, and each edit is shown before the work moves on —\n      you always see exactly what changed, where.</li>\n    <li><strong>Every run shows its result.</strong> Validations, test runs,\n      builds: the command and its outcome appear inline, green or red, not\n      summarized away.</li>\n    <li><strong>Context is explicit.</strong> The composer carries context\n      chips — which workspace, which files the session is focused on — and\n      you can add more to point the agent at the right material.</li>\n    <li><strong>The agent asks before the big moves.</strong> It will edit\n      and validate on its own, but shipping — a deploy, a publish, a store\n      submission — is proposed, not assumed.</li>\n    <li><strong>Sessions are durable.</strong> A running session keeps\n      working while you do something else; finished ones stay in the list\n      as a record of what was done and why.</li>\n  </ul>\n\n  <div class=\"callout\">\n    <strong>Your workspace, visibly.</strong> The agent works on the same\n    files the Apps, Nodes, and Pipelines tabs show — create a pipeline in a\n    session and it appears in the Pipelines list; open it on the canvas and\n    it is the same artifact. There is no hidden second workspace.\n  </div>\n\n  <!-- ========================================================== -->\n  <!-- THE LOOP                                                    -->\n  <!-- ========================================================== -->\n\n  <h2>From a sentence to production</h2>\n  <ol class=\"steps\">\n    <li><span class=\"st\">Describe the goal</span><span class=\"sd\">Start a new session and say what you want in plain language — the outcome, not the implementation. \"My team needs to search our policy documents and get cited answers.\"</span></li>\n    <li><span class=\"st\">Agree on the plan</span><span class=\"sd\">The agent reads your workspace, says what it intends to build — which artifacts, which components — and you confirm or redirect before it starts.</span></li>\n    <li><span class=\"st\">Watch it build</span><span class=\"sd\">Scaffolds run, files appear, lanes get wired. Every edit is a visible diff; every validation shows its result. Interrupt and course-correct at any point.</span></li>\n    <li><span class=\"st\">Try it</span><span class=\"sd\">Run the pipeline on sample data, open the app in preview, check the output. \"The summary is too long\" is a perfectly good instruction — iteration is just more conversation.</span></li>\n    <li><span class=\"st\">Ship it</span><span class=\"sd\">When it works, say so: the agent deploys a version and publishes it to the audience you choose — yourself first, then the team, then the store if it is going public.</span></li>\n    <li><span class=\"st\">Come back anytime</span><span class=\"sd\">Next week's change request is a new session: \"add an export button\", \"the OCR step misses rotated scans\". The agent picks up the workspace as it is now.</span></li>\n  </ol>\n\n  <!-- ========================================================== -->\n  <!-- VOCABULARY                                                  -->\n  <!-- ========================================================== -->\n\n  <h2>Vocabulary worth keeping straight</h2>\n  <div class=\"table-scroll\">\n  <table>\n    <tr><th>Term</th><th>Means exactly</th><th>Never confuse with</th></tr>\n    <tr><td><strong>session</strong></td><td>One agent task and its full conversation — edits, runs, decisions</td><td>a chat that vanishes when closed</td></tr>\n    <tr><td><strong>workspace</strong></td><td>Your cloud project — the apps, nodes, and pipelines the sidebar tabs list</td><td>a sandbox the agent keeps for itself</td></tr>\n    <tr><td><strong>tool call</strong></td><td>One visible agent action in the transcript: an edit, a validation, a run</td><td>a message the agent writes</td></tr>\n    <tr><td><strong>diff</strong></td><td>The exact file change an edit made, shown inline</td><td>a summary of what changed</td></tr>\n    <tr><td><strong>context chip</strong></td><td>A file or scope attached to the composer to focus the agent</td><td>the agent's whole knowledge of the workspace</td></tr>\n    <tr><td><strong>deploy</strong></td><td>Version an artifact into the server registry</td><td>publish</td></tr>\n    <tr><td><strong>publish</strong></td><td>Bind a deployed version to a rung (<code>@me</code>, <code>@team</code>, <code>@public</code>)</td><td>deploy</td></tr>\n    <tr><td><strong>coding agent</strong></td><td>This — the agent that builds artifacts in your workspace</td><td>an agent <em>component inside</em> a pipeline (see the Pipelines page)</td></tr>\n  </table>\n  </div>\n\n  <!-- ========================================================== -->\n  <!-- GETTING STARTED                                             -->\n  <!-- ========================================================== -->\n\n  <h2>Where to go next</h2>\n  <div class=\"grid2\">\n    <div class=\"card\">\n      <h4>Start with one sentence</h4>\n      <p>Open the Agent tab, start a session, and describe one thing you\n      want: a small pipeline, a simple app, a fix. Watch how the agent\n      works before giving it something big — trust is built per diff.</p>\n    </div>\n    <div class=\"card\">\n      <h4>Know what it is building</h4>\n      <p>The companion pages explain the artifacts themselves — RocketRide\n      Apps, RocketRide Pipelines, and RocketRide Nodes. You do not need\n      them to use the agent, but they make you a sharper director.</p>\n    </div>\n  </div>\n\n  <footer>\n    RocketRide Agent — introduction for new users. Describes the coding\n    agent experience as designed; details may evolve as it ships.\n  </footer>\n\n</div>\n\n</body>\n</html>\n";

/** The Apps introduction, as a complete standalone HTML document. */
const APPS_INTRO_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>RocketRide Apps — An Introduction</title>\n<style>\n  :root {\n    --bg: #f7f8fa;\n    --surface: #ffffff;\n    --ink: #1c2230;\n    --ink-soft: #4b5568;\n    --ink-faint: #8a93a6;\n    --accent: #2f5fe0;\n    --accent-soft: #e8eefc;\n    --line: #e3e7ee;\n    --code-bg: #f1f3f7;\n    --good: #1d8a4e;\n    --warn: #b26a00;\n    --radius: 10px;\n  }\n\n  * { box-sizing: border-box; }\n\n  body {\n    margin: 0;\n    background: var(--bg);\n    color: var(--ink);\n    font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n    font-size: 16px;\n    line-height: 1.65;\n  }\n\n  .wrap {\n    max-width: 880px;\n    margin: 0 auto;\n    padding: 0 28px 96px;\n  }\n\n  /* ============================================================ */\n  /* HERO                                                          */\n  /* ============================================================ */\n\n  header.hero {\n    background: linear-gradient(160deg, #1c2745 0%, #24356b 55%, #2f4a9e 100%);\n    color: #eef2ff;\n    padding: 72px 28px 64px;\n  }\n  header.hero .inner {\n    max-width: 880px;\n    margin: 0 auto;\n  }\n  header.hero .kicker {\n    text-transform: uppercase;\n    letter-spacing: 0.14em;\n    font-size: 12px;\n    font-weight: 600;\n    color: #9db2e8;\n    margin-bottom: 14px;\n  }\n  header.hero h1 {\n    margin: 0 0 18px;\n    font-size: 40px;\n    line-height: 1.15;\n    font-weight: 700;\n  }\n  header.hero p.lede {\n    margin: 0;\n    max-width: 640px;\n    font-size: 19px;\n    line-height: 1.6;\n    color: #cdd8f5;\n  }\n\n  /* ============================================================ */\n  /* TYPOGRAPHY                                                    */\n  /* ============================================================ */\n\n  h2 {\n    font-size: 26px;\n    margin: 64px 0 16px;\n    padding-top: 8px;\n    border-top: 1px solid var(--line);\n  }\n  h3 {\n    font-size: 19px;\n    margin: 32px 0 10px;\n  }\n  p { margin: 0 0 16px; color: var(--ink-soft); }\n  strong { color: var(--ink); }\n  li { color: var(--ink-soft); margin-bottom: 8px; }\n\n  code {\n    font-family: \"Cascadia Code\", Consolas, \"SF Mono\", Menlo, monospace;\n    font-size: 0.88em;\n    background: var(--code-bg);\n    border: 1px solid var(--line);\n    border-radius: 4px;\n    padding: 1px 5px;\n    color: #33415e;\n  }\n\n  pre {\n    background: #1e2433;\n    color: #d7deed;\n    border-radius: var(--radius);\n    padding: 18px 20px;\n    overflow-x: auto;\n    font-size: 13.5px;\n    line-height: 1.55;\n  }\n  pre code {\n    background: none;\n    border: none;\n    padding: 0;\n    color: inherit;\n    font-size: inherit;\n  }\n\n  /* ============================================================ */\n  /* CARDS, TABLES, CALLOUTS                                       */\n  /* ============================================================ */\n\n  .card {\n    background: var(--surface);\n    border: 1px solid var(--line);\n    border-radius: var(--radius);\n    padding: 20px 24px;\n    margin: 20px 0;\n  }\n\n  .grid2 {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 16px;\n    margin: 20px 0;\n  }\n  @media (max-width: 640px) { .grid2 { grid-template-columns: 1fr; } }\n\n  .grid2 .card { margin: 0; }\n  .card h4 {\n    margin: 0 0 8px;\n    font-size: 15px;\n    color: var(--accent);\n  }\n  .card p { margin: 0; font-size: 14.5px; }\n\n  table {\n    width: 100%;\n    border-collapse: collapse;\n    margin: 20px 0;\n    background: var(--surface);\n    border: 1px solid var(--line);\n    border-radius: var(--radius);\n    overflow: hidden;\n    font-size: 14.5px;\n  }\n  th, td {\n    text-align: left;\n    padding: 10px 14px;\n    border-bottom: 1px solid var(--line);\n    vertical-align: top;\n  }\n  th {\n    background: var(--accent-soft);\n    color: #22376e;\n    font-weight: 600;\n  }\n  tr:last-child td { border-bottom: none; }\n  td { color: var(--ink-soft); }\n  .table-scroll { overflow-x: auto; }\n\n  .callout {\n    border-left: 4px solid var(--accent);\n    background: var(--accent-soft);\n    border-radius: 0 var(--radius) var(--radius) 0;\n    padding: 14px 18px;\n    margin: 20px 0;\n    font-size: 15px;\n    color: #2a3b66;\n  }\n  .callout strong { color: #1d2c52; }\n\n  /* ============================================================ */\n  /* DIAGRAMS                                                      */\n  /* ============================================================ */\n\n  .diagram {\n    background: var(--surface);\n    border: 1px solid var(--line);\n    border-radius: var(--radius);\n    padding: 28px 20px;\n    margin: 24px 0;\n    text-align: center;\n    overflow-x: auto;\n  }\n  .diagram .caption {\n    font-size: 13px;\n    color: var(--ink-faint);\n    margin-top: 14px;\n  }\n\n  .flow {\n    display: inline-flex;\n    align-items: stretch;\n    gap: 0;\n    flex-wrap: wrap;\n    justify-content: center;\n  }\n  .flow .node {\n    background: var(--accent-soft);\n    border: 1px solid #c3d2f5;\n    border-radius: 8px;\n    padding: 12px 18px;\n    min-width: 130px;\n  }\n  .flow .node .t { font-weight: 600; font-size: 15px; color: #22376e; }\n  .flow .node .s { font-size: 12.5px; color: #5a6ea0; margin-top: 2px; }\n  .flow .arrow {\n    display: flex;\n    align-items: center;\n    padding: 0 10px;\n    color: var(--ink-faint);\n    font-size: 20px;\n  }\n\n  .shellmock {\n    display: grid;\n    grid-template-columns: 150px 1fr 90px;\n    grid-template-rows: 1fr 34px;\n    gap: 4px;\n    max-width: 560px;\n    margin: 0 auto;\n    height: 230px;\n    font-size: 13px;\n    text-align: left;\n  }\n  .shellmock > div {\n    border: 1px solid #c3d2f5;\n    border-radius: 6px;\n    padding: 8px 10px;\n    background: var(--accent-soft);\n    color: #3a4d85;\n  }\n  .shellmock .client {\n    background: #fff;\n    border-style: dashed;\n    border-color: var(--accent);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: var(--accent);\n    font-weight: 600;\n  }\n  .shellmock .status {\n    grid-column: 1 / span 3;\n    display: flex;\n    align-items: center;\n    gap: 8px;\n  }\n  .shellmock .dot {\n    width: 8px; height: 8px; border-radius: 50%;\n    background: var(--good);\n    display: inline-block;\n  }\n  .shellmock .zone-label { font-weight: 600; margin-bottom: 4px; display: block; }\n  .shellmock .zone-sub { font-size: 11.5px; color: #6a7cae; }\n\n  /* ============================================================ */\n  /* LIFECYCLE STEPS                                               */\n  /* ============================================================ */\n\n  .steps { counter-reset: step; margin: 24px 0; padding: 0; list-style: none; }\n  .steps li {\n    position: relative;\n    padding: 0 0 22px 52px;\n    margin: 0;\n  }\n  .steps li::before {\n    counter-increment: step;\n    content: counter(step);\n    position: absolute;\n    left: 0; top: 0;\n    width: 32px; height: 32px;\n    border-radius: 50%;\n    background: var(--accent);\n    color: #fff;\n    font-weight: 700;\n    font-size: 15px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n  .steps li::after {\n    content: \"\";\n    position: absolute;\n    left: 15px; top: 36px; bottom: 2px;\n    width: 2px;\n    background: var(--line);\n  }\n  .steps li:last-child::after { display: none; }\n  .steps li .st { font-weight: 600; color: var(--ink); display: block; margin-bottom: 2px; }\n  .steps li .sd { font-size: 14.5px; color: var(--ink-soft); }\n\n  .rungs { display: flex; gap: 12px; flex-wrap: wrap; margin: 18px 0; }\n  .rung {\n    flex: 1;\n    min-width: 180px;\n    background: var(--surface);\n    border: 1px solid var(--line);\n    border-radius: var(--radius);\n    padding: 16px 18px;\n  }\n  .rung .tag {\n    font-family: Consolas, monospace;\n    font-weight: 700;\n    font-size: 15px;\n    color: var(--accent);\n    display: block;\n    margin-bottom: 6px;\n  }\n  .rung p { margin: 0; font-size: 13.5px; }\n\n  footer {\n    margin-top: 72px;\n    padding-top: 20px;\n    border-top: 1px solid var(--line);\n    font-size: 13px;\n    color: var(--ink-faint);\n  }\n</style>\n</head>\n<body>\n\n<header class=\"hero\">\n  <div class=\"inner\">\n    <div class=\"kicker\">RocketRide Platform</div>\n    <h1>RocketRide Apps</h1>\n    <p class=\"lede\">\n      A RocketRide app is a web application that runs inside the RocketRide\n      platform shell and puts AI pipelines to work for real users — document\n      processing, chat over your data, agents, dashboards. This page explains\n      what apps are, how people use them, and how they are built and shipped.\n    </p>\n  </div>\n</header>\n\n<div class=\"wrap\">\n\n  <!-- ========================================================== -->\n  <!-- WHAT IS AN APP                                              -->\n  <!-- ========================================================== -->\n\n  <h2>What is a RocketRide app?</h2>\n  <p>\n    Think of the RocketRide platform as three layers working together. A person\n    uses an <strong>app</strong> — a friendly, interactive user interface. The\n    app runs <strong>pipelines</strong> — AI and data workflows that execute on\n    the RocketRide server. Pipelines are assembled from\n    <strong>pipeline components</strong> — a catalog of building blocks for\n    parsing documents, calling language models, searching, storing, and\n    connecting to outside systems.\n  </p>\n\n  <div class=\"diagram\">\n    <div class=\"flow\">\n      <div class=\"node\"><div class=\"t\">Person</div><div class=\"s\">uses</div></div>\n      <div class=\"arrow\">&#8594;</div>\n      <div class=\"node\"><div class=\"t\">App</div><div class=\"s\">React UI in the shell</div></div>\n      <div class=\"arrow\">&#8594;</div>\n      <div class=\"node\"><div class=\"t\">Pipeline</div><div class=\"s\">runs on the server</div></div>\n      <div class=\"arrow\">&#8594;</div>\n      <div class=\"node\"><div class=\"t\">Components</div><div class=\"s\">from the catalog</div></div>\n    </div>\n    <div class=\"caption\">The solution model: each layer has a clean contract with the next.</div>\n  </div>\n\n  <p>\n    Technically, an app is a React application loaded by the\n    <strong>platform shell</strong> — a thin host that provides the frame around\n    every app: the app switcher, sign-in and account management, settings,\n    themes, and a live connection to the RocketRide server. The app itself\n    focuses purely on its own experience; everything platform-shaped is\n    provided for it.\n  </p>\n\n  <div class=\"grid2\">\n    <div class=\"card\">\n      <h4>What apps are for</h4>\n      <p>Turning AI pipelines into products people can actually use: upload a\n      contract and get a summary, chat with a knowledge base, monitor a data\n      feed, review generated reports — without anyone touching code or\n      configuration.</p>\n    </div>\n    <div class=\"card\">\n      <h4>What the shell does for them</h4>\n      <p>Authentication, the server connection, workspace persistence, theming,\n      settings, billing and subscriptions, and a store to discover apps. Apps\n      never handle credentials or manage their own connections.</p>\n    </div>\n  </div>\n\n  <!-- ========================================================== -->\n  <!-- HOW A USER INTERACTS                                        -->\n  <!-- ========================================================== -->\n\n  <h2>How a user experiences an app</h2>\n  <p>\n    A user opens the RocketRide shell in their browser (or inside VS Code),\n    signs in once, and picks an app from the app switcher or the store. The\n    shell draws the consistent frame; the app fills the client area with its\n    own interface.\n  </p>\n\n  <div class=\"diagram\">\n    <div class=\"shellmock\">\n      <div>\n        <span class=\"zone-label\">Sidebar</span>\n        <span class=\"zone-sub\">App switcher, the app's navigation, account &amp; theme footer</span>\n      </div>\n      <div class=\"client\">Client area — the app itself</div>\n      <div>\n        <span class=\"zone-label\">Debug</span>\n        <span class=\"zone-sub\">ALT+D event log</span>\n      </div>\n      <div class=\"status\"><span class=\"dot\"></span> Connected &nbsp;&middot;&nbsp; Status bar (connection identity + the app's status messages)</div>\n    </div>\n    <div class=\"caption\">The shell's screen zones. The app owns the client area and can opt into a sidebar and status bar.</div>\n  </div>\n\n  <h3>The everyday experience</h3>\n  <ul>\n    <li><strong>One sign-in for everything.</strong> The shell handles\n      authentication; every app the user opens already knows who they are.</li>\n    <li><strong>Discover apps in the store.</strong> Public apps have listings\n      with an icon, description, README, and categories. Apps can be free,\n      subscription-based, or paywalled — subscriptions and checkout are handled\n      by the platform.</li>\n    <li><strong>Everything remembers where you left it.</strong> Each app's\n      preferences and state persist per user on the server, so the same\n      workspace follows the user across browsers and machines.</li>\n    <li><strong>Settings, not code.</strong> Apps declare user-editable\n      settings (just like a VS Code extension does), and they appear in the\n      shell's standard Settings overlay.</li>\n    <li><strong>Themes apply everywhere.</strong> Light and dark palettes flow\n      through every app instantly via shared theme tokens.</li>\n    <li><strong>Live results.</strong> Because pipelines run on the server and\n      stream results back, users see AI output token by token, watch task\n      status update in real time, and can close their laptop without killing a\n      long-running job.</li>\n  </ul>\n\n  <!-- ========================================================== -->\n  <!-- HOW APPS ARE BUILT                                          -->\n  <!-- ========================================================== -->\n\n  <h2>How apps are built</h2>\n  <p>\n    Apps are built by developers in a <strong>RocketRide workspace</strong> —\n    an ordinary project folder with an <code>./apps</code> directory for app\n    projects and a <code>./pipelines</code> directory for pipeline files. The\n    development experience centers on the <strong>App Builder</strong>, a\n    dedicated tool with everything needed to create, preview, package, and\n    ship an app.\n  </p>\n\n  <h3>Creating an app</h3>\n  <p>\n    New apps are always created through the platform's scaffold — the App\n    Builder's <strong>New App wizard</strong> (or the API, for automation). The\n    wizard asks for a name, a template (Blank or Dashboard), and which frame\n    elements the app wants: a navigation sidebar, a status footer, and\n    document tabs. It then generates a complete, working app with the correct\n    build configuration baked in.\n  </p>\n\n  <h3>The dev loop</h3>\n  <p>\n    Opening an app in the App Builder starts a live development session:\n    dependencies install, a dev server builds the app on every save, and the\n    <strong>Preview</strong> shows the app running inside a real shell session\n    — with device frames for desktop, tablet, and phone. Only the developer\n    sees the in-progress version; a personal <em>dev overlay</em> on the server\n    keeps development invisible to everyone else.\n  </p>\n\n  <div class=\"table-scroll\">\n  <table>\n    <tr><th>App Builder tab</th><th>The question it answers</th></tr>\n    <tr><td><strong>Dashboard</strong></td><td>What state is my app in, and what should I do next? Includes the full deployment history and a message thread with the store review team.</td></tr>\n    <tr><td><strong>Design</strong></td><td>Does it look and behave right? Live preview, code, a gallery of stock UI components, plus event, console, and error feeds.</td></tr>\n    <tr><td><strong>Package</strong></td><td>Is the app complete and buildable? Name, description, icon, README, and packaging.</td></tr>\n    <tr><td><strong>Store</strong></td><td>Is the public listing ready? Billing mode, pricing plans, and the store requirements checklist.</td></tr>\n    <tr><td><strong>Deploy</strong></td><td>Which versions exist, and who is served which one?</td></tr>\n  </table>\n  </div>\n\n  <h3>What the code looks like</h3>\n  <p>\n    An app is standard React and TypeScript. Everything platform-provided —\n    layout, hooks, stock UI components, the server connection — is imported\n    from one package, <code>'shell'</code>. The app's root renders an\n    <code>AppLayout</code> and declares its frame with props:\n  </p>\n\n<pre><code>import { AppLayout, useShellConnection } from 'shell';\n\nexport default function App() {\n  const { client, isConnected } = useShellConnection();\n  if (!client || !isConnected) return &lt;div&gt;Connecting...&lt;/div&gt;;\n\n  return (\n    &lt;AppLayout sidebar={&lt;Nav /&gt;} showStatus&gt;\n      &lt;MyContent /&gt;\n    &lt;/AppLayout&gt;\n  );\n}</code></pre>\n\n  <p>\n    The shell provides a rich toolkit so apps stay consistent and small:\n    connection and identity hooks, per-user preference and state persistence,\n    a typed platform event bus, a VS Code-style document and file-tree system\n    for file-oriented apps, and a full set of stock UI components — all themed\n    automatically.\n  </p>\n\n  <h3>Putting a pipeline inside an app</h3>\n  <p>\n    This is the heart of most apps. A pipeline is a JSON file with a\n    <code>.pipe</code> extension; the app imports it like any module, starts it\n    through the shared client, and then talks to the running task — sending\n    data, uploading files, or chatting — while streaming results straight into\n    the UI:\n  </p>\n\n<pre><code>import summarizer from './summarizer.pipe';\n\nconst { token } = await client.use({ pipeline: summarizer });\n\nawait client.chat({\n  token,\n  question: 'Summarize the uploaded contract.',\n  onSSE: async (type, data) =&gt; {\n    setStreamText((prev) =&gt; prev + String(data.text ?? ''));\n  },\n});</code></pre>\n\n  <div class=\"callout\">\n    <strong>Every user gets their own pipeline instance.</strong> When an app\n    starts a pipeline, it runs and bills under the signed-in user's identity,\n    with their own isolated state. For shared services — one big index, one\n    warm model for a whole team — a pipeline is deployed separately as its own\n    project and the app simply addresses the running task.\n  </div>\n\n  <p>\n    Secrets never ship inside an app. Pipeline configurations reference\n    placeholders like <code>${ROCKETRIDE_OPENAI_KEY}</code>, and the server\n    substitutes real values from the organization's layered environment\n    (org, team, and user levels) at run time.\n  </p>\n\n  <!-- ========================================================== -->\n  <!-- SHIPPING                                                    -->\n  <!-- ========================================================== -->\n\n  <h2>Shipping: deploy, publish, and the store</h2>\n  <p>\n    RocketRide uses two verbs with precise meanings, and they are worth\n    learning early because they are never interchangeable:\n  </p>\n\n  <div class=\"grid2\">\n    <div class=\"card\">\n      <h4>Deploy</h4>\n      <p>Ship a snapshot of the app's <em>source</em> to the server. The server\n      builds it and records the result as the next immutable registry version\n      (v1, v2, v3, ...). Deploying changes nothing a user sees.</p>\n    </div>\n    <div class=\"card\">\n      <h4>Publish</h4>\n      <p>Bind an already-deployed version to an <em>audience</em>. Publishing\n      moves a pointer — it never rebuilds anything. The same verb covers first\n      release, updates, promotion, and instant rollback.</p>\n    </div>\n  </div>\n\n  <p>Audiences are called <strong>rungs</strong>, and there are three:</p>\n\n  <div class=\"rungs\">\n    <div class=\"rung\">\n      <span class=\"tag\">@me</span>\n      <p>Only the developer. The place to try a deployed build exactly as users\n      will receive it.</p>\n    </div>\n    <div class=\"rung\">\n      <span class=\"tag\">@team/&lt;name&gt;</span>\n      <p>A team in the organization. Serves immediately — ideal for internal\n      tools and staged rollouts.</p>\n    </div>\n    <div class=\"rung\">\n      <span class=\"tag\">@public</span>\n      <p>The app store. Adds a human review step: submit a version, converse\n      with the reviewer, and go live on approval.</p>\n    </div>\n  </div>\n\n  <h3>The path from idea to store</h3>\n  <ol class=\"steps\">\n    <li><span class=\"st\">Create</span><span class=\"sd\">Scaffold the app with the New App wizard and shape it in the live preview.</span></li>\n    <li><span class=\"st\">Package</span><span class=\"sd\">Give it a name, description, icon, and README; the readiness checklist confirms it is complete.</span></li>\n    <li><span class=\"st\">Deploy</span><span class=\"sd\">Upload the source; the server builds it into an immutable version with a build log.</span></li>\n    <li><span class=\"st\">Publish to @me, then @team</span><span class=\"sd\">Verify the real deployed build yourself, then share it with the team.</span></li>\n    <li><span class=\"st\">Submit to the store</span><span class=\"sd\">For public apps: complete the store checklist, submit the version for review, and message the review team in the app's own conversation thread.</span></li>\n    <li><span class=\"st\">Update and roll back freely</span><span class=\"sd\">New versions deploy alongside old ones; moving an audience between versions is instant, in both directions.</span></li>\n  </ol>\n\n  <p>\n    Because published apps are served from versioned, immutable URLs, two\n    audiences can safely be on different versions at once, rollback takes\n    effect immediately, and nothing ever mutates underneath a user.\n  </p>\n\n  <h3>Identity and trust</h3>\n  <p>\n    Every app id has the form <code>&lt;developerId&gt;.&lt;name&gt;</code> —\n    for example <code>acme.brandy</code>. An organization claims its developer\n    id once and can then only deploy apps inside that namespace, so an app's id\n    reliably tells users who published it.\n  </p>\n\n  <!-- ========================================================== -->\n  <!-- VOCABULARY                                                  -->\n  <!-- ========================================================== -->\n\n  <h2>Vocabulary worth keeping straight</h2>\n  <div class=\"table-scroll\">\n  <table>\n    <tr><th>Term</th><th>Means exactly</th><th>Never confuse with</th></tr>\n    <tr><td><strong>deploy</strong></td><td>Version an artifact into the server registry</td><td>publish</td></tr>\n    <tr><td><strong>publish</strong></td><td>Bind a deployed version to a rung</td><td>deploy</td></tr>\n    <tr><td><strong>rung</strong></td><td><code>@me</code>, <code>@team/&lt;name&gt;</code>, <code>@public</code></td><td>organizations (there is no org rung)</td></tr>\n    <tr><td><strong>registry version</strong></td><td>Server-assigned integer (v1, v2, ...)</td><td>the package's own semver</td></tr>\n    <tr><td><strong>UI component</strong></td><td>A React component in an app</td><td>pipeline component</td></tr>\n    <tr><td><strong>pipeline component</strong></td><td>A processing node inside a <code>.pipe</code></td><td>UI component</td></tr>\n    <tr><td><strong>task / token</strong></td><td>One running pipeline instance and its handle</td><td>the pipeline definition itself</td></tr>\n    <tr><td><strong>shell</strong></td><td>The platform host that loads apps and owns the frame</td><td>the app itself</td></tr>\n  </table>\n  </div>\n\n  <!-- ========================================================== -->\n  <!-- GETTING STARTED                                             -->\n  <!-- ========================================================== -->\n\n  <h2>Where to go next</h2>\n  <div class=\"grid2\">\n    <div class=\"card\">\n      <h4>Using apps</h4>\n      <p>Open the RocketRide shell, sign in, and browse the store. Installed\n      and subscribed apps appear in your app switcher; each one remembers your\n      preferences and state automatically.</p>\n    </div>\n    <div class=\"card\">\n      <h4>Building apps</h4>\n      <p>Open a RocketRide workspace, run the App Builder's New App wizard,\n      and start from the live preview. The full developer guide lives in the\n      workspace docs under <code>.rocketride/docs/</code> —\n      start with <code>ROCKETRIDE_README.md</code>, then\n      <code>ROCKETRIDE_APPS.md</code>.</p>\n    </div>\n  </div>\n\n  <footer>\n    RocketRide Apps — introduction for new users.\n  </footer>\n\n</div>\n\n</body>\n</html>\n";

/** The Nodes introduction, as a complete standalone HTML document. */
const NODES_INTRO_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>RocketRide Nodes — An Introduction</title>\n<style>\n  :root {\n    --bg: #f7f8fa;\n    --surface: #ffffff;\n    --ink: #1c2230;\n    --ink-soft: #4b5568;\n    --ink-faint: #8a93a6;\n    --accent: #c46a10;\n    --accent-soft: #fdf0e0;\n    --accent-border: #eed3ae;\n    --accent-ink: #7a4a10;\n    --line: #e3e7ee;\n    --code-bg: #f1f3f7;\n    --good: #1d8a4e;\n    --radius: 10px;\n  }\n\n  * { box-sizing: border-box; }\n\n  body {\n    margin: 0;\n    background: var(--bg);\n    color: var(--ink);\n    font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n    font-size: 16px;\n    line-height: 1.65;\n  }\n\n  .wrap {\n    max-width: 880px;\n    margin: 0 auto;\n    padding: 0 28px 96px;\n  }\n\n  /* ============================================================ */\n  /* HERO                                                          */\n  /* ============================================================ */\n\n  header.hero {\n    background: linear-gradient(160deg, #3d2410 0%, #6b3d12 55%, #9a5713 100%);\n    color: #fdf3e6;\n    padding: 72px 28px 64px;\n  }\n  header.hero .inner {\n    max-width: 880px;\n    margin: 0 auto;\n  }\n  header.hero .kicker {\n    text-transform: uppercase;\n    letter-spacing: 0.14em;\n    font-size: 12px;\n    font-weight: 600;\n    color: #e8b26a;\n    margin-bottom: 14px;\n  }\n  header.hero h1 {\n    margin: 0 0 18px;\n    font-size: 40px;\n    line-height: 1.15;\n    font-weight: 700;\n  }\n  header.hero p.lede {\n    margin: 0;\n    max-width: 640px;\n    font-size: 19px;\n    line-height: 1.6;\n    color: #f2d9b8;\n  }\n\n  /* ============================================================ */\n  /* TYPOGRAPHY                                                    */\n  /* ============================================================ */\n\n  h2 {\n    font-size: 26px;\n    margin: 64px 0 16px;\n    padding-top: 8px;\n    border-top: 1px solid var(--line);\n  }\n  h3 {\n    font-size: 19px;\n    margin: 32px 0 10px;\n  }\n  p { margin: 0 0 16px; color: var(--ink-soft); }\n  strong { color: var(--ink); }\n  li { color: var(--ink-soft); margin-bottom: 8px; }\n\n  code {\n    font-family: \"Cascadia Code\", Consolas, \"SF Mono\", Menlo, monospace;\n    font-size: 0.88em;\n    background: var(--code-bg);\n    border: 1px solid var(--line);\n    border-radius: 4px;\n    padding: 1px 5px;\n    color: #33415e;\n  }\n\n  pre {\n    background: #1e2433;\n    color: #d7deed;\n    border-radius: var(--radius);\n    padding: 18px 20px;\n    overflow-x: auto;\n    font-size: 13.5px;\n    line-height: 1.55;\n  }\n  pre code {\n    background: none;\n    border: none;\n    padding: 0;\n    color: inherit;\n    font-size: inherit;\n  }\n\n  /* ============================================================ */\n  /* CARDS, TABLES, CALLOUTS                                       */\n  /* ============================================================ */\n\n  .card {\n    background: var(--surface);\n    border: 1px solid var(--line);\n    border-radius: var(--radius);\n    padding: 20px 24px;\n    margin: 20px 0;\n  }\n\n  .grid2 {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 16px;\n    margin: 20px 0;\n  }\n  @media (max-width: 640px) { .grid2 { grid-template-columns: 1fr; } }\n\n  .grid2 .card { margin: 0; }\n  .card h4 {\n    margin: 0 0 8px;\n    font-size: 15px;\n    color: var(--accent);\n  }\n  .card p { margin: 0; font-size: 14.5px; }\n  .card p + p { margin-top: 8px; }\n\n  table {\n    width: 100%;\n    border-collapse: collapse;\n    margin: 20px 0;\n    background: var(--surface);\n    border: 1px solid var(--line);\n    border-radius: var(--radius);\n    overflow: hidden;\n    font-size: 14.5px;\n  }\n  th, td {\n    text-align: left;\n    padding: 10px 14px;\n    border-bottom: 1px solid var(--line);\n    vertical-align: top;\n  }\n  th {\n    background: var(--accent-soft);\n    color: var(--accent-ink);\n    font-weight: 600;\n  }\n  tr:last-child td { border-bottom: none; }\n  td { color: var(--ink-soft); }\n  .table-scroll { overflow-x: auto; }\n\n  .callout {\n    border-left: 4px solid var(--accent);\n    background: var(--accent-soft);\n    border-radius: 0 var(--radius) var(--radius) 0;\n    padding: 14px 18px;\n    margin: 20px 0;\n    font-size: 15px;\n    color: var(--accent-ink);\n  }\n  .callout strong { color: #5c360a; }\n\n  /* ============================================================ */\n  /* DIAGRAMS                                                      */\n  /* ============================================================ */\n\n  .diagram {\n    background: var(--surface);\n    border: 1px solid var(--line);\n    border-radius: var(--radius);\n    padding: 28px 20px;\n    margin: 24px 0;\n    text-align: center;\n    overflow-x: auto;\n  }\n  .diagram .caption {\n    font-size: 13px;\n    color: var(--ink-faint);\n    margin-top: 14px;\n  }\n\n  .flow {\n    display: inline-flex;\n    align-items: stretch;\n    gap: 0;\n    flex-wrap: wrap;\n    justify-content: center;\n  }\n  .flow .node {\n    background: var(--accent-soft);\n    border: 1px solid var(--accent-border);\n    border-radius: 8px;\n    padding: 12px 18px;\n    min-width: 110px;\n  }\n  .flow .node .t { font-weight: 600; font-size: 15px; color: var(--accent-ink); }\n  .flow .node .s { font-size: 12.5px; color: #a4762e; margin-top: 2px; }\n  .flow .arrow {\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    justify-content: center;\n    padding: 0 10px;\n    color: var(--ink-faint);\n    font-size: 20px;\n  }\n  .flow .arrow .lane {\n    font-family: Consolas, monospace;\n    font-size: 11px;\n    color: var(--accent);\n    margin-top: -2px;\n  }\n\n  /* The palette-card mock: how a custom node renders in the designer */\n  .npcard {\n    width: 360px;\n    max-width: 100%;\n    margin: 0 auto;\n    background: #fff;\n    border: 1.5px solid #d8dbe0;\n    border-radius: 14px;\n    text-align: left;\n    box-shadow: 0 3px 14px rgba(30,40,55,0.08);\n    font-size: 14px;\n  }\n  .npcard .head {\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    background: #f3f4f6;\n    border-bottom: 1px solid #e6e8eb;\n    border-radius: 13px 13px 0 0;\n    padding: 13px 16px;\n  }\n  .npcard .icon {\n    width: 36px; height: 36px;\n    border-radius: 8px;\n    background: var(--accent);\n    color: #fff;\n    font-weight: 800;\n    font-size: 13px;\n    font-family: Consolas, monospace;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    flex-shrink: 0;\n  }\n  .npcard .ttl { font-weight: 600; color: #333; font-size: 16px; }\n  .npcard .sub { font-size: 10.5px; letter-spacing: 0.1em; color: #8a8a8a; font-weight: 600; margin-top: 2px; }\n  .npcard .glyphs { margin-left: auto; color: #9aa0a8; font-size: 16px; letter-spacing: 6px; }\n  .npcard .body { display: flex; justify-content: space-between; padding: 12px 16px 6px; }\n  .npcard .lane { padding: 6px 0; color: #555; }\n  .npcard .lane.out { text-align: right; }\n  .npcard .auto {\n    font-size: 8.5px;\n    font-weight: 700;\n    letter-spacing: 0.05em;\n    text-transform: uppercase;\n    color: #999;\n    border: 1px solid #ddd;\n    border-radius: 3px;\n    padding: 0 4px;\n    margin-right: 7px;\n    vertical-align: 2px;\n  }\n  .npcard .sect {\n    margin: 4px 16px 0;\n    border-top: 1px solid #efefef;\n    padding: 7px 0 4px;\n    font-size: 13px;\n  }\n  .npcard .sect .lbl {\n    font-size: 9.5px;\n    font-weight: 700;\n    letter-spacing: 0.09em;\n    color: #a8a8a8;\n    display: block;\n    margin-bottom: 2px;\n  }\n  .npcard .toolrow { font-family: Consolas, monospace; color: #555; padding: 3px 0 3px 8px; }\n  .npcard .invoke { text-align: center; color: #555; padding: 8px 0 14px; }\n  .npcard .invoke .cnt { font-size: 11px; font-family: Consolas, monospace; color: #a3a9b0; margin-left: 5px; }\n\n  /* ============================================================ */\n  /* LIFECYCLE STEPS                                               */\n  /* ============================================================ */\n\n  .steps { counter-reset: step; margin: 24px 0; padding: 0; list-style: none; }\n  .steps li {\n    position: relative;\n    padding: 0 0 22px 52px;\n    margin: 0;\n  }\n  .steps li::before {\n    counter-increment: step;\n    content: counter(step);\n    position: absolute;\n    left: 0; top: 0;\n    width: 32px; height: 32px;\n    border-radius: 50%;\n    background: var(--accent);\n    color: #fff;\n    font-weight: 700;\n    font-size: 15px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n  .steps li::after {\n    content: \"\";\n    position: absolute;\n    left: 15px; top: 36px; bottom: 2px;\n    width: 2px;\n    background: var(--line);\n  }\n  .steps li:last-child::after { display: none; }\n  .steps li .st { font-weight: 600; color: var(--ink); display: block; margin-bottom: 2px; }\n  .steps li .sd { font-size: 14.5px; color: var(--ink-soft); }\n\n  footer {\n    margin-top: 72px;\n    padding-top: 20px;\n    border-top: 1px solid var(--line);\n    font-size: 13px;\n    color: var(--ink-faint);\n  }\n</style>\n</head>\n<body>\n\n<header class=\"hero\">\n  <div class=\"inner\">\n    <div class=\"kicker\">RocketRide Platform</div>\n    <h1>RocketRide Nodes</h1>\n    <p class=\"lede\">\n      Every box in a RocketRide pipeline is a component from the platform\n      catalog. Nodes are how you add your own: small Python packages that\n      become first-class pipeline components — with their own card in the\n      designer palette, their own configuration, and the same versioned\n      deployment as everything else on the platform.\n    </p>\n  </div>\n</header>\n\n<div class=\"wrap\">\n\n  <!-- ========================================================== -->\n  <!-- WHAT IS A NODE                                              -->\n  <!-- ========================================================== -->\n\n  <h2>What is a node?</h2>\n  <p>\n    The platform ships with a large catalog of pipeline components — parsers,\n    language models, vector stores, agents, tools. A <strong>node</strong> is\n    a custom component you write yourself when the catalog does not have what\n    you need: a connector to your ticketing system, a domain-specific\n    classifier, an in-house enrichment step, a proprietary data source.\n  </p>\n  <p>\n    Once published, your node is indistinguishable from a built-in component.\n    It appears in Rocket Builder's pipeline palette with its own icon, title, and\n    configuration form; it wires into pipelines through the same typed lanes;\n    agents can call its tools; and pipelines that use it run it on the server\n    like any other component.\n  </p>\n\n  <div class=\"diagram\">\n    <div class=\"flow\">\n      <div class=\"node\"><div class=\"t\">webhook</div><div class=\"s\">built-in</div></div>\n      <div class=\"arrow\">&#8594;<span class=\"lane\">tags</span></div>\n      <div class=\"node\"><div class=\"t\">parse</div><div class=\"s\">built-in</div></div>\n      <div class=\"arrow\">&#8594;<span class=\"lane\">text</span></div>\n      <div class=\"node\" style=\"border-width:2px; border-color:var(--accent)\"><div class=\"t\">sentiment_tagger</div><div class=\"s\">YOUR NODE</div></div>\n      <div class=\"arrow\">&#8594;<span class=\"lane\">text</span></div>\n      <div class=\"node\"><div class=\"t\">response</div><div class=\"s\">built-in</div></div>\n    </div>\n    <div class=\"caption\">A custom node sits in a pipeline exactly like a catalog component — same lanes, same wiring.</div>\n  </div>\n\n  <p>\n    On disk, a node is a folder in your workspace under\n    <code>./nodes/src/nodes/&lt;name&gt;/</code>: a service manifest that\n    describes the component to the platform, and a couple of Python classes\n    that implement its behavior. <strong>The files are the truth</strong> —\n    every tool that touches a node is a lens over that folder, and the VS Code\n    Explorer and editor remain the file manager and the place code gets\n    written.\n  </p>\n\n  <!-- ========================================================== -->\n  <!-- TWO KINDS                                                   -->\n  <!-- ========================================================== -->\n\n  <h2>Two kinds of node</h2>\n  <p>\n    A node is either a <strong>source</strong> or a <strong>filter</strong> —\n    chosen when the node is created, and fixed for its lifetime. They are\n    genuinely different things, with different contracts:\n  </p>\n\n  <div class=\"grid2\">\n    <div class=\"card\">\n      <h4>Filter — sits in the data flow</h4>\n      <p>A filter consumes typed lanes and emits typed lanes. Each input lane\n      it accepts <em>is</em> a handler method: accepting the <code>text</code>\n      lane means implementing <code>writeText()</code>. Whatever the handler\n      emits downstream — by calling the platform's write methods — becomes the\n      node's output lanes.</p>\n      <p>Examples: a classifier, an enricher, a redactor, a format\n      converter.</p>\n    </div>\n    <div class=\"card\">\n      <h4>Source — brings data in</h4>\n      <p>A source is a pipeline entry point and has no input lanes at all.\n      Its contract is two methods: <code>scanObjects()</code> enumerates the\n      objects that exist (tickets, rows, files, messages), and\n      <code>renderObject()</code> produces each one's content into the\n      pipeline.</p>\n      <p>Examples: a ticket-system feed, a CRM export, a proprietary file\n      format reader.</p>\n    </div>\n  </div>\n\n  <div class=\"callout\">\n    <strong>Outputs are inferred, never declared.</strong> You do not write an\n    \"outputs\" list into a manifest and hope it matches the code. The platform\n    scans your handler code for what it actually emits — a call that writes\n    classifications means the node produces a classifications lane — and the\n    palette card shows those outputs tagged \"auto\". The code cannot drift from\n    the definition, because the code <em>is</em> the definition.\n  </div>\n\n  <!-- ========================================================== -->\n  <!-- ANATOMY                                                     -->\n  <!-- ========================================================== -->\n\n  <h2>Inside a node package</h2>\n  <p>A typical filter node's folder looks like this:</p>\n\n<pre><code>nodes/src/nodes/sentiment_tagger/\n  services.sentiment.json     the service manifest: identity, config fields, invoke needs\n  IGlobal.py                  task-level lifecycle and shared state\n  IInstance.py                the lane handlers - where the work happens\n  helpers/prompts.py          any supporting code you like\n  requirements.txt            Python dependencies, resolved against the platform\n  sentiment.svg               the palette icon\n  README.md                   documentation that ships with the node</code></pre>\n\n  <h3>The service manifest</h3>\n  <p>\n    The manifest (<code>services.&lt;name&gt;.json</code>) is what the platform\n    reads to draw and configure your component: its title, icon, and protocol;\n    its <strong>configuration fields</strong> (typed, with defaults, ranges,\n    and secure password-style entries — these render as the component's\n    settings form in Rocket Builder); and its <strong>invoke\n    requirements</strong> — for example, \"this node needs exactly one LLM\n    attached\", the same control-plane contract built-in components use.\n  </p>\n\n  <h3>The handler code</h3>\n  <p>\n    The Python side is deliberately small. A filter implements one\n    <code>write*</code> method per lane it consumes; a source implements the\n    scan/render pair. Optional lifecycle overrides (instance startup and\n    teardown, flush, incremental scanning) are available when you need them,\n    and a node that declared an LLM requirement can simply call\n    <code>self.invoke('llm', prompt)</code> to use whatever model the\n    pipeline author attached:\n  </p>\n\n<pre><code>def writeText(self, text: str) -> None:\n    \"\"\"Handle text lane input.\"\"\"\n    labels = self.invoke('llm', self._prompt(text))\n    if labels.confidence >= self.IGlobal.threshold:\n        self.instance.writeClassifications('sentiment',\n            labels.confidence, labels.as_dict())\n    if self.IGlobal.emit_text:\n        self.instance.writeText(text)</code></pre>\n\n  <h3>Agent tools</h3>\n  <p>\n    A node can also expose <strong>tools</strong> — methods decorated with\n    input and output schemas that agents can call, exactly like the platform's\n    own tool components. One node can be both a lane filter and a tool\n    provider at once.\n  </p>\n\n  <h3>One package, several services</h3>\n  <p>\n    A single node package may carry several manifests — each one a separate\n    component in the palette, with its own title, icon, protocol, and\n    configuration, all sharing the package's Python code. This is the same\n    pattern the platform's own webhook family uses (chat, dropper, and tools\n    are one package). All services in a package share the node's kind: a\n    package is sources or filters, never a mix.\n  </p>\n\n  <!-- ========================================================== -->\n  <!-- THE NODE BUILDER                                            -->\n  <!-- ========================================================== -->\n\n  <h2>The Node Builder</h2>\n  <p>\n    Nodes are developed in the <strong>Node Builder</strong> — the sibling of\n    the pipeline designer, with the same three activity tabs over your work:\n    Design, Develop, and Deploy. Its centerpiece is the <strong>live palette\n    preview</strong>: your node's card, rendered exactly as the pipeline\n    designer will draw it, and directly editable.\n  </p>\n\n  <div class=\"diagram\">\n    <div class=\"npcard\">\n      <div class=\"head\">\n        <div class=\"icon\">ST</div>\n        <div>\n          <div class=\"ttl\">Sentiment Tagger</div>\n          <div class=\"sub\">TOOL &#183; FILTER</div>\n        </div>\n        <div class=\"glyphs\">&#9881; &#8942;</div>\n      </div>\n      <div class=\"body\">\n        <div>\n          <div class=\"lane\">Text</div>\n          <div class=\"lane\">Documents</div>\n          <div class=\"lane\" style=\"color:#a3a9b0; font-size:12px\">+ lane</div>\n        </div>\n        <div>\n          <div class=\"lane out\"><span class=\"auto\">auto</span>Classifications</div>\n          <div class=\"lane out\"><span class=\"auto\">auto</span>Text</div>\n        </div>\n      </div>\n      <div class=\"sect\">\n        <span class=\"lbl\">TOOLS</span>\n        <div class=\"toolrow\">analyze(text, labels?)</div>\n      </div>\n      <div class=\"invoke\">LLM <span class=\"cnt\">min 1 &#183; max 1</span></div>\n    </div>\n    <div class=\"caption\">The live node card: every part of it edits the node. Output lanes carry \"auto\" tags because they are inferred from the code.</div>\n  </div>\n\n  <p>Everything on the card is direct manipulation:</p>\n  <ul>\n    <li><strong>Click an input lane</strong> and its handler code slides in\n      beside the card — read-only, with an \"Edit in VS Code\" button that opens\n      the real file. Adding a lane writes the handler stub; removing one\n      retires an empty stub.</li>\n    <li><strong>The gear</strong> shows the node's configuration form exactly\n      as pipeline authors will see it, with a pencil beside each field that\n      jumps to its definition in the manifest.</li>\n    <li><strong>The kebab menu</strong> holds identity: title, protocol,\n      prefix, class types, description.</li>\n    <li><strong>The icon</strong> is a picker over the <code>.svg</code> files\n      in the node's folder.</li>\n  </ul>\n\n  <div class=\"table-scroll\">\n  <table>\n    <tr><th>Node Builder tab</th><th>The question it answers</th></tr>\n    <tr><td><strong>Design</strong></td><td>What does my component look like, and what does it do? The live palette card, with code views one click away.</td></tr>\n    <tr><td><strong>Develop</strong></td><td>Is the package complete and correct? Per-service metadata, the package contents, a Validate pass (manifests, unique protocols, the produces scan, dependency resolution), and a Test button that runs the node in a local engine with sample input on every lane.</td></tr>\n    <tr><td><strong>Deploy</strong></td><td>Which versions exist, and which team runs which one?</td></tr>\n  </table>\n  </div>\n\n  <p>\n    New nodes start from the <strong>New Node wizard</strong> — a name and a\n    kind (source or filter) — which scaffolds the folder with a working\n    manifest and class files, and the sidebar lists every node folder in the\n    workspace alongside your pipelines.\n  </p>\n\n  <!-- ========================================================== -->\n  <!-- SHIPPING                                                    -->\n  <!-- ========================================================== -->\n\n  <h2>Shipping: nodes deploy exactly like pipelines</h2>\n  <p>\n    If you have read the pipelines introduction, you already know this part —\n    that is the point. Nodes ride the same artifact rail as every other\n    RocketRide artifact: publish an immutable version, pin a team to it,\n    promote and roll back by moving the pointer.\n  </p>\n\n  <ol class=\"steps\">\n    <li><span class=\"st\">Build and test locally</span><span class=\"sd\">The Node Builder's Test runs your node inside a local engine with a generated harness pipeline — sample input in, emitted lanes out — and Validate checks the manifests, protocols, inferred outputs, and dependencies.</span></li>\n    <li><span class=\"st\">Publish a version</span><span class=\"sd\">Publishing gathers the whole folder — manifests, code, icon, requirements, even binary assets — into one self-contained artifact and records it as the next immutable version (v1, v2, v3, ...).</span></li>\n    <li><span class=\"st\">Pin a team</span><span class=\"sd\">Deploying points a team at one version. From then on, that team's pipeline runs materialize the node and load it alongside the built-in catalog.</span></li>\n    <li><span class=\"st\">Promote and roll back freely</span><span class=\"sd\">Different teams can run different versions at once; moving a team between versions is instant, in both directions.</span></li>\n  </ol>\n\n  <div class=\"callout\">\n    <strong>Version resolution happens at run time.</strong> A pipeline never\n    embeds a copy of your node — it uses whatever version is deployed to its\n    team when it runs. Ship a fix, repoint the team, and every pipeline that\n    uses the node picks it up on its next run; roll the pointer back to undo.\n    Nodes have no schedules of their own — they ride along with the pipelines\n    that call them.\n  </div>\n\n  <!-- ========================================================== -->\n  <!-- VOCABULARY                                                  -->\n  <!-- ========================================================== -->\n\n  <h2>Vocabulary worth keeping straight</h2>\n  <div class=\"table-scroll\">\n  <table>\n    <tr><th>Term</th><th>Means exactly</th><th>Never confuse with</th></tr>\n    <tr><td><strong>node</strong></td><td>A custom pipeline-component package you write (a folder under <code>nodes/src/nodes</code>)</td><td>a component instance placed in one pipeline</td></tr>\n    <tr><td><strong>service</strong></td><td>One palette component defined by one manifest; a package may carry several</td><td>the package itself</td></tr>\n    <tr><td><strong>filter</strong></td><td>A node that consumes and emits lanes via <code>write*</code> handlers</td><td>source</td></tr>\n    <tr><td><strong>source</strong></td><td>A node that brings data in via <code>scanObjects</code> + <code>renderObject</code>; no input lanes</td><td>filter</td></tr>\n    <tr><td><strong>lane handler</strong></td><td>The method behind an input lane — the lane and the handler are one thing</td><td>a declared list of inputs</td></tr>\n    <tr><td><strong>produces</strong></td><td>Output lanes, inferred from what the code emits</td><td>something you declare by hand</td></tr>\n    <tr><td><strong>manifest</strong></td><td><code>services.&lt;name&gt;.json</code> — identity, config fields, invoke requirements</td><td>the Python implementation</td></tr>\n    <tr><td><strong>pin</strong></td><td>The pointer from a team to one immutable node version</td><td>the version itself</td></tr>\n  </table>\n  </div>\n\n  <!-- ========================================================== -->\n  <!-- GETTING STARTED                                             -->\n  <!-- ========================================================== -->\n\n  <h2>Where to go next</h2>\n  <div class=\"grid2\">\n    <div class=\"card\">\n      <h4>Before writing a node</h4>\n      <p>Check the catalog first — the component you need may already exist,\n      and built-in components come with no code to maintain. Reach for a node\n      when the capability is genuinely yours: your systems, your formats,\n      your domain logic.</p>\n    </div>\n    <div class=\"card\">\n      <h4>Start from the scaffold</h4>\n      <p>Create the node through the New Node wizard, get the Test harness\n      green on sample input, and only then wire it into a real pipeline.\n      The companion pages — RocketRide Apps and RocketRide Pipelines — cover\n      the platform this all plugs into.</p>\n    </div>\n  </div>\n\n  <footer>\n    RocketRide Nodes — introduction for new users. Describes the Node Builder\n    experience as designed; details may evolve as it ships.\n  </footer>\n\n</div>\n\n</body>\n</html>\n";

/** The Pipelines introduction, as a complete standalone HTML document. */
const PIPES_INTRO_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>RocketRide Pipelines — An Introduction</title>\n<style>\n  :root {\n    --bg: #f7f8fa;\n    --surface: #ffffff;\n    --ink: #1c2230;\n    --ink-soft: #4b5568;\n    --ink-faint: #8a93a6;\n    --accent: #0d7d6c;\n    --accent-soft: #e4f4f1;\n    --accent-border: #bfe0da;\n    --accent-ink: #0f5248;\n    --line: #e3e7ee;\n    --code-bg: #f1f3f7;\n    --good: #1d8a4e;\n    --radius: 10px;\n  }\n\n  * { box-sizing: border-box; }\n\n  body {\n    margin: 0;\n    background: var(--bg);\n    color: var(--ink);\n    font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n    font-size: 16px;\n    line-height: 1.65;\n  }\n\n  .wrap {\n    max-width: 880px;\n    margin: 0 auto;\n    padding: 0 28px 96px;\n  }\n\n  /* ============================================================ */\n  /* HERO                                                          */\n  /* ============================================================ */\n\n  header.hero {\n    background: linear-gradient(160deg, #12332e 0%, #14524a 55%, #17705f 100%);\n    color: #eafaf6;\n    padding: 72px 28px 64px;\n  }\n  header.hero .inner {\n    max-width: 880px;\n    margin: 0 auto;\n  }\n  header.hero .kicker {\n    text-transform: uppercase;\n    letter-spacing: 0.14em;\n    font-size: 12px;\n    font-weight: 600;\n    color: #8fd0c3;\n    margin-bottom: 14px;\n  }\n  header.hero h1 {\n    margin: 0 0 18px;\n    font-size: 40px;\n    line-height: 1.15;\n    font-weight: 700;\n  }\n  header.hero p.lede {\n    margin: 0;\n    max-width: 640px;\n    font-size: 19px;\n    line-height: 1.6;\n    color: #c4e8e0;\n  }\n\n  /* ============================================================ */\n  /* TYPOGRAPHY                                                    */\n  /* ============================================================ */\n\n  h2 {\n    font-size: 26px;\n    margin: 64px 0 16px;\n    padding-top: 8px;\n    border-top: 1px solid var(--line);\n  }\n  h3 {\n    font-size: 19px;\n    margin: 32px 0 10px;\n  }\n  p { margin: 0 0 16px; color: var(--ink-soft); }\n  strong { color: var(--ink); }\n  li { color: var(--ink-soft); margin-bottom: 8px; }\n\n  code {\n    font-family: \"Cascadia Code\", Consolas, \"SF Mono\", Menlo, monospace;\n    font-size: 0.88em;\n    background: var(--code-bg);\n    border: 1px solid var(--line);\n    border-radius: 4px;\n    padding: 1px 5px;\n    color: #33415e;\n  }\n\n  pre {\n    background: #1e2433;\n    color: #d7deed;\n    border-radius: var(--radius);\n    padding: 18px 20px;\n    overflow-x: auto;\n    font-size: 13.5px;\n    line-height: 1.55;\n  }\n  pre code {\n    background: none;\n    border: none;\n    padding: 0;\n    color: inherit;\n    font-size: inherit;\n  }\n\n  /* ============================================================ */\n  /* CARDS, TABLES, CALLOUTS                                       */\n  /* ============================================================ */\n\n  .card {\n    background: var(--surface);\n    border: 1px solid var(--line);\n    border-radius: var(--radius);\n    padding: 20px 24px;\n    margin: 20px 0;\n  }\n\n  .grid2 {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 16px;\n    margin: 20px 0;\n  }\n  .grid3 {\n    display: grid;\n    grid-template-columns: 1fr 1fr 1fr;\n    gap: 16px;\n    margin: 20px 0;\n  }\n  @media (max-width: 640px) { .grid2, .grid3 { grid-template-columns: 1fr; } }\n\n  .grid2 .card, .grid3 .card { margin: 0; }\n  .card h4 {\n    margin: 0 0 8px;\n    font-size: 15px;\n    color: var(--accent);\n  }\n  .card p { margin: 0; font-size: 14.5px; }\n\n  table {\n    width: 100%;\n    border-collapse: collapse;\n    margin: 20px 0;\n    background: var(--surface);\n    border: 1px solid var(--line);\n    border-radius: var(--radius);\n    overflow: hidden;\n    font-size: 14.5px;\n  }\n  th, td {\n    text-align: left;\n    padding: 10px 14px;\n    border-bottom: 1px solid var(--line);\n    vertical-align: top;\n  }\n  th {\n    background: var(--accent-soft);\n    color: var(--accent-ink);\n    font-weight: 600;\n  }\n  tr:last-child td { border-bottom: none; }\n  td { color: var(--ink-soft); }\n  .table-scroll { overflow-x: auto; }\n\n  .callout {\n    border-left: 4px solid var(--accent);\n    background: var(--accent-soft);\n    border-radius: 0 var(--radius) var(--radius) 0;\n    padding: 14px 18px;\n    margin: 20px 0;\n    font-size: 15px;\n    color: var(--accent-ink);\n  }\n  .callout strong { color: #0b3d36; }\n\n  /* ============================================================ */\n  /* DIAGRAMS                                                      */\n  /* ============================================================ */\n\n  .diagram {\n    background: var(--surface);\n    border: 1px solid var(--line);\n    border-radius: var(--radius);\n    padding: 28px 20px;\n    margin: 24px 0;\n    text-align: center;\n    overflow-x: auto;\n  }\n  .diagram .caption {\n    font-size: 13px;\n    color: var(--ink-faint);\n    margin-top: 14px;\n  }\n\n  .flow {\n    display: inline-flex;\n    align-items: stretch;\n    gap: 0;\n    flex-wrap: wrap;\n    justify-content: center;\n  }\n  .flow .node {\n    background: var(--accent-soft);\n    border: 1px solid var(--accent-border);\n    border-radius: 8px;\n    padding: 12px 18px;\n    min-width: 110px;\n  }\n  .flow .node .t { font-weight: 600; font-size: 15px; color: var(--accent-ink); }\n  .flow .node .s { font-size: 12.5px; color: #3f7a70; margin-top: 2px; }\n  .flow .node.alt {\n    background: #fdf3e4;\n    border-color: #ecd4a8;\n  }\n  .flow .node.alt .t { color: #7a5410; }\n  .flow .node.alt .s { color: #9a742e; }\n  .flow .arrow {\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    justify-content: center;\n    padding: 0 10px;\n    color: var(--ink-faint);\n    font-size: 20px;\n  }\n  .flow .arrow .lane {\n    font-family: Consolas, monospace;\n    font-size: 11px;\n    color: var(--accent);\n    margin-top: -2px;\n  }\n\n  /* control-plane diagram */\n  .ctrl {\n    display: inline-block;\n    text-align: center;\n  }\n  .ctrl .row { display: flex; justify-content: center; gap: 14px; margin-top: 6px; }\n  .ctrl .stem {\n    width: 2px; height: 22px;\n    background: #ecd4a8;\n    margin: 0 auto;\n  }\n\n  /* ============================================================ */\n  /* LIFECYCLE STEPS                                               */\n  /* ============================================================ */\n\n  .steps { counter-reset: step; margin: 24px 0; padding: 0; list-style: none; }\n  .steps li {\n    position: relative;\n    padding: 0 0 22px 52px;\n    margin: 0;\n  }\n  .steps li::before {\n    counter-increment: step;\n    content: counter(step);\n    position: absolute;\n    left: 0; top: 0;\n    width: 32px; height: 32px;\n    border-radius: 50%;\n    background: var(--accent);\n    color: #fff;\n    font-weight: 700;\n    font-size: 15px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n  .steps li::after {\n    content: \"\";\n    position: absolute;\n    left: 15px; top: 36px; bottom: 2px;\n    width: 2px;\n    background: var(--line);\n  }\n  .steps li:last-child::after { display: none; }\n  .steps li .st { font-weight: 600; color: var(--ink); display: block; margin-bottom: 2px; }\n  .steps li .sd { font-size: 14.5px; color: var(--ink-soft); }\n\n  footer {\n    margin-top: 72px;\n    padding-top: 20px;\n    border-top: 1px solid var(--line);\n    font-size: 13px;\n    color: var(--ink-faint);\n  }\n</style>\n</head>\n<body>\n\n<header class=\"hero\">\n  <div class=\"inner\">\n    <div class=\"kicker\">RocketRide Platform</div>\n    <h1>RocketRide Pipelines</h1>\n    <p class=\"lede\">\n      A pipeline is the working heart of RocketRide: a graph of AI and data\n      components — parsers, models, vector stores, agents — that runs on the\n      server and does the actual work. This page explains what pipelines are,\n      how they are put together, how they run, and how apps and scripts talk\n      to them.\n    </p>\n  </div>\n</header>\n\n<div class=\"wrap\">\n\n  <!-- ========================================================== -->\n  <!-- WHAT IS A PIPELINE                                          -->\n  <!-- ========================================================== -->\n\n  <h2>What is a pipeline?</h2>\n  <p>\n    A pipeline describes a flow of data through a series of\n    <strong>pipeline components</strong>: data enters through a\n    <strong>source</strong> (a chat box, a file upload, a folder, a Telegram\n    bot), moves through processing components (parse a document, extract text\n    from images, chunk it, embed it, ask a language model, store it), and\n    leaves through a <strong>response</strong> component that returns results\n    to whoever asked — or lands in a store, if the job is ingestion.\n  </p>\n\n  <div class=\"diagram\">\n    <div class=\"flow\">\n      <div class=\"node\"><div class=\"t\">chat</div><div class=\"s\">source</div></div>\n      <div class=\"arrow\">&#8594;<span class=\"lane\">questions</span></div>\n      <div class=\"node\"><div class=\"t\">qdrant</div><div class=\"s\">vector search</div></div>\n      <div class=\"arrow\">&#8594;<span class=\"lane\">documents</span></div>\n      <div class=\"node\"><div class=\"t\">llm_openai</div><div class=\"s\">language model</div></div>\n      <div class=\"arrow\">&#8594;<span class=\"lane\">answers</span></div>\n      <div class=\"node\"><div class=\"t\">response</div><div class=\"s\">back to the caller</div></div>\n    </div>\n    <div class=\"caption\">A chat-with-your-documents (RAG) pipeline: question in, retrieved context, answer out.</div>\n  </div>\n\n  <p>\n    The whole thing lives in a single file with a <code>.pipe</code> extension\n    — plain JSON listing the components and how they connect. That one file is\n    the complete, self-contained definition: it can be edited visually on a\n    canvas, checked into git, embedded inside an app, or deployed to a server\n    and run on a schedule.\n  </p>\n\n  <div class=\"grid2\">\n    <div class=\"card\">\n      <h4>What pipelines are for</h4>\n      <p>Document processing and OCR, retrieval-augmented chat (RAG), AI\n      agents with tools and memory, data extraction, audio and video\n      understanding, text-to-speech, web research, guardrailed LLM services —\n      any AI workflow you can draw as boxes and arrows.</p>\n    </div>\n    <div class=\"card\">\n      <h4>Where they run</h4>\n      <p>Always on the RocketRide server — never in the browser or your\n      script. Your code is a remote control holding a task token; closing your\n      laptop does not stop a running pipeline.</p>\n    </div>\n  </div>\n\n  <!-- ========================================================== -->\n  <!-- BUILDING BLOCKS                                             -->\n  <!-- ========================================================== -->\n\n  <h2>The building blocks</h2>\n\n  <h3>Components and the catalog</h3>\n  <p>\n    Every box in a pipeline is a component chosen from the platform's\n    <strong>component catalog</strong> — the definitive list of what exists,\n    what each component accepts and produces, and how it is configured. The\n    catalog spans several families:\n  </p>\n\n  <div class=\"table-scroll\">\n  <table>\n    <tr><th>Family</th><th>Examples</th><th>Job</th></tr>\n    <tr><td><strong>Sources</strong></td><td><code>chat</code>, <code>webhook</code>, <code>dropper</code>, <code>filesys</code>, <code>telegram</code></td><td>Bring data in: conversations, uploads, files, bot messages.</td></tr>\n    <tr><td><strong>Processing</strong></td><td><code>parse</code>, <code>ocr</code>, <code>audio_transcribe</code>, <code>preprocessor_langchain</code>, <code>embedding_transformer</code></td><td>Turn raw files into text, chunks, and vectors.</td></tr>\n    <tr><td><strong>Models</strong></td><td><code>llm_openai</code>, <code>llm_anthropic</code>, <code>image_vision_*</code>, <code>tts_openai</code></td><td>Language models, vision, and speech.</td></tr>\n    <tr><td><strong>Stores</strong></td><td><code>qdrant</code>, <code>postgres</code> (pgvector), <code>db_postgres</code>, <code>graph_neo4j</code></td><td>Vector similarity search, text-to-SQL over tables, graph queries.</td></tr>\n    <tr><td><strong>Agents</strong></td><td><code>agent_rocketride</code>, <code>agent_crewai_manager</code>, <code>agent_deepagent</code></td><td>Autonomous reasoning with an LLM, memory, tools, and sub-agents.</td></tr>\n    <tr><td><strong>Tools</strong></td><td><code>tool_tavily</code>, <code>tool_firecrawl</code>, <code>tool_python</code>, <code>mcp_client</code></td><td>Capabilities an agent can call: search, scrape, run code, MCP servers.</td></tr>\n    <tr><td><strong>Responses</strong></td><td><code>response_answers</code>, <code>response_text</code>, <code>response_json</code>, <code>response_audio</code></td><td>Return results to the calling client, typed by kind.</td></tr>\n  </table>\n  </div>\n\n  <h3>Lanes: typed connections</h3>\n  <p>\n    Components connect through <strong>lanes</strong> — typed data channels.\n    A connection is valid only when the upstream component produces the lane\n    the downstream one accepts: <code>text</code> for plain text,\n    <code>documents</code> for embeddable chunks, <code>questions</code> for\n    prompts heading to a model, <code>answers</code> for what comes back,\n    plus <code>tags</code> (file metadata), <code>table</code>,\n    <code>json</code>, and streamed media lanes for <code>image</code>,\n    <code>audio</code>, and <code>video</code>.\n  </p>\n  <p>\n    Types keep pipelines honest. You cannot wire a raw file upload straight\n    into a text chunker — a parser has to sit in between to turn\n    <code>tags</code> into <code>text</code>. When lanes do not match, a\n    converter component bridges them: OCR turns images into text, a\n    transcriber turns audio into text, a frame grabber turns video into\n    images.\n  </p>\n\n  <h3>The control plane: agents, LLMs, and tools</h3>\n  <p>\n    Not every connection carries data. Some components <em>invoke</em> others:\n    an agent needs an LLM to think with, tools to act with, and memory to keep\n    notes in. These are <strong>control connections</strong> — a second kind\n    of wiring that says \"this component is at that one's service.\"\n  </p>\n\n  <div class=\"diagram\">\n    <div class=\"ctrl\">\n      <div class=\"flow\">\n        <div class=\"node\"><div class=\"t\">chat</div><div class=\"s\">source</div></div>\n        <div class=\"arrow\">&#8594;<span class=\"lane\">questions</span></div>\n        <div class=\"node alt\"><div class=\"t\">agent</div><div class=\"s\">orchestrates</div></div>\n        <div class=\"arrow\">&#8594;<span class=\"lane\">answers</span></div>\n        <div class=\"node\"><div class=\"t\">response</div><div class=\"s\">back to the caller</div></div>\n      </div>\n      <div class=\"stem\"></div>\n      <div class=\"row\">\n        <div class=\"node alt\"><div class=\"t\">llm</div><div class=\"s\">thinks</div></div>\n        <div class=\"node alt\"><div class=\"t\">memory</div><div class=\"s\">remembers</div></div>\n        <div class=\"node alt\"><div class=\"t\">web search</div><div class=\"s\">tool</div></div>\n        <div class=\"node alt\"><div class=\"t\">python</div><div class=\"s\">tool</div></div>\n      </div>\n    </div>\n    <div class=\"caption\">An agent pipeline: data flows left to right; the LLM, memory, and tools hang below on the control plane.</div>\n  </div>\n\n  <p>\n    This composes into real depth: agents can delegate to sub-agents, call\n    other agents as tools, run an entire inline sub-pipeline as a single tool,\n    or reach external capabilities through MCP servers — while the data path\n    through the pipeline stays simple.\n  </p>\n\n  <h3>Profiles: sensible configuration</h3>\n  <p>\n    Configurable components ship with named <strong>profiles</strong> — presets\n    that carry the fiddly details (model ids, token limits, hosts, ports) so a\n    working configuration is usually just a profile name plus an API key:\n  </p>\n\n<pre><code>\"config\": {\n  \"profile\": \"openai-5\",\n  \"openai-5\": { \"apikey\": \"${ROCKETRIDE_OPENAI_KEY}\" },\n  \"parameters\": {}\n}</code></pre>\n\n  <div class=\"callout\">\n    <strong>Secrets never live in the file.</strong> Configuration references\n    placeholders like <code>${ROCKETRIDE_OPENAI_KEY}</code>, and the server\n    substitutes real values when the pipeline starts — drawn from the merged\n    environment: your workspace <code>.env</code> plus secrets an admin has\n    stored at the organization, team, or user level. A pipeline can run with\n    no local secrets at all, and a <code>.pipe</code> file is always safe to\n    share or commit.\n  </div>\n\n  <!-- ========================================================== -->\n  <!-- THE FILE                                                    -->\n  <!-- ========================================================== -->\n\n  <h2>What a .pipe file looks like</h2>\n  <p>\n    Here is a complete, runnable pipeline — simple chat with a language model.\n    Components come first; the file's permanent identity\n    (<code>project_id</code>, a unique GUID) sits at the bottom:\n  </p>\n\n<pre><code>{\n  \"components\": [\n    { \"id\": \"chat_1\", \"provider\": \"chat\",\n      \"config\": { \"hideForm\": true, \"mode\": \"Source\",\n                  \"parameters\": {}, \"type\": \"chat\" } },\n\n    { \"id\": \"llm_openai_1\", \"provider\": \"llm_openai\",\n      \"config\": { \"profile\": \"openai-5\",\n                  \"openai-5\": { \"apikey\": \"${ROCKETRIDE_OPENAI_KEY}\" },\n                  \"parameters\": {} },\n      \"input\": [{ \"lane\": \"questions\", \"from\": \"chat_1\" }] },\n\n    { \"id\": \"response_answers_1\", \"provider\": \"response_answers\",\n      \"config\": { \"laneName\": \"answers\" },\n      \"input\": [{ \"lane\": \"answers\", \"from\": \"llm_openai_1\" }] }\n  ],\n  \"project_id\": \"85be2a13-ad93-49ed-a1e1-4b0f763ca618\",\n  \"viewport\": { \"x\": 0, \"y\": 0, \"zoom\": 1 },\n  \"version\": 1\n}</code></pre>\n\n  <p>\n    Each component names its <code>provider</code> from the catalog, carries\n    a <code>config</code>, and lists its <code>input</code> connections —\n    which lane, from which component. That is the entire format; everything\n    else is choosing the right components and wiring them with matching lanes.\n  </p>\n\n  <!-- ========================================================== -->\n  <!-- COMMON SHAPES                                               -->\n  <!-- ========================================================== -->\n\n  <h2>The shapes you will build most</h2>\n\n  <div class=\"grid2\">\n    <div class=\"card\">\n      <h4>Chat with your documents (RAG)</h4>\n      <p><code>chat &#8594; embedding &#8594; vector store &#8594; prompt &#8594; llm &#8594; response</code><br><br>\n      The question is embedded, similar document chunks are retrieved, and the\n      LLM answers grounded in that context.</p>\n    </div>\n    <div class=\"card\">\n      <h4>Document ingestion</h4>\n      <p><code>webhook &#8594; parse &#8594; chunk &#8594; embedding &#8594; vector store</code><br><br>\n      Uploads are parsed, chunked, embedded, and stored. No response\n      component — the store is the destination.</p>\n    </div>\n    <div class=\"card\">\n      <h4>AI agent with tools</h4>\n      <p><code>chat &#8594; agent &#8594; response</code>, with an LLM, memory,\n      and tools on the control plane.<br><br>\n      The agent plans, calls tools (search, scraping, code, databases, MCP),\n      and synthesizes an answer.</p>\n    </div>\n    <div class=\"card\">\n      <h4>Multi-modal processing</h4>\n      <p><code>webhook &#8594; parse</code>, fanning out: images through OCR,\n      audio through transcription, all merging back into one text flow for\n      indexing or analysis.</p>\n    </div>\n    <div class=\"card\">\n      <h4>Structured extraction</h4>\n      <p><code>webhook &#8594; parse &#8594; extract_data &#8594; response</code><br><br>\n      An LLM-backed extractor pulls a defined set of fields (invoice numbers,\n      totals, dates) out of unstructured documents as clean JSON.</p>\n    </div>\n    <div class=\"card\">\n      <h4>Guardrailed LLM service</h4>\n      <p><code>chat &#8594; guardrails &#8594; llm &#8594; guardrails &#8594; response</code><br><br>\n      Deterministic checks on the way in (prompt injection, topics) and out\n      (PII, format, grounding) — no extra model calls.</p>\n    </div>\n  </div>\n\n  <p>\n    Beyond these: text-to-speech and audio responses, video understanding,\n    image cleanup and vision Q&amp;A, pose and depth estimation, web research\n    agents, graph-backed memory, and text-to-SQL over live databases — all\n    from the same catalog, all wired the same way.\n  </p>\n\n  <h3>Picking a store</h3>\n  <div class=\"table-scroll\">\n  <table>\n    <tr><th>You need</th><th>Family</th><th>How it behaves</th></tr>\n    <tr><td>\"Find content like this\" — semantic search over documents</td><td><strong>Vector</strong> (<code>qdrant</code>, pgvector, Pinecone, ...)</td><td>Documents go in through an embedder; questions come in the same way and similar chunks come back.</td></tr>\n    <tr><td>Exact answers over structured tables — filters, joins, sums</td><td><strong>Relational</strong> (<code>db_postgres</code>, <code>db_mysql</code>, ...)</td><td>An LLM writes SQL from the natural-language question and runs it against your existing tables.</td></tr>\n    <tr><td>\"How is A connected to B\" — relationship traversal</td><td><strong>Graph</strong> (Neo4j, FalkorDB, built-in)</td><td>An LLM writes Cypher from the question and queries an existing graph.</td></tr>\n  </table>\n  </div>\n  <p>\n    Built-in <code>rocketride_*</code> variants of all three families need no\n    external server — the fastest way to prototype before pointing the same\n    wiring at production infrastructure.\n  </p>\n\n  <!-- ========================================================== -->\n  <!-- RUNNING                                                     -->\n  <!-- ========================================================== -->\n\n  <h2>How pipelines run</h2>\n  <p>\n    A <code>.pipe</code> file is a definition; a running instance of it is a\n    <strong>task</strong>. Starting one returns a <strong>token</strong> — the\n    handle for everything that follows. Apps and scripts use the SDK\n    (TypeScript or Python) the same way:\n  </p>\n\n<pre><code>// Start the pipeline once and keep the token\nconst { token } = await client.use({ pipeline, useExisting: true });\n\n// Talk to it — here, a chat source, streaming the answer token by token\nawait client.chat({\n  token,\n  question: 'What does the uploaded contract say about termination?',\n  onSSE: async (type, data) =&gt; {\n    setStreamText((prev) =&gt; prev + String(data.text ?? ''));\n  },\n});</code></pre>\n\n  <ul>\n    <li><strong>The source determines the verb.</strong> A <code>chat</code>\n      source takes <code>client.chat()</code>; <code>webhook</code> and\n      <code>dropper</code> sources take <code>client.send()</code> and file\n      uploads.</li>\n    <li><strong>Start once, reuse the token.</strong> Starting a pipeline is\n      expensive; a well-behaved client starts it once per session, reattaches\n      after a reload, and lets an idle timeout (<code>ttl</code>) clean up.</li>\n    <li><strong>Results stream live.</strong> Server-sent events deliver model\n      output as it is generated, and push events report task status — so UIs\n      show progress in real time.</li>\n    <li><strong>Each run is isolated per user.</strong> When an app starts a\n      pipeline, the signed-in user gets their own instance, their own state,\n      and their own billing — automatically.</li>\n  </ul>\n\n  <h3>From your workspace to production</h3>\n  <ol class=\"steps\">\n    <li><span class=\"st\">Author</span><span class=\"sd\">Write the <code>.pipe</code> file in your workspace's <code>./pipelines</code> folder — by hand, on the visual canvas, or with an AI agent; the catalog and schemas in <code>.rocketride/</code> are the source of truth.</span></li>\n    <li><span class=\"st\">Validate</span><span class=\"sd\">The platform checks the whole graph before anything runs — unknown components, mismatched lanes, missing configuration, and broken wiring are rejected with messages that point at the exact component to fix.</span></li>\n    <li><span class=\"st\">Run and iterate</span><span class=\"sd\">Start it against your development server, drive it from a script or an app, and watch its events and logs live.</span></li>\n    <li><span class=\"st\">Embed or deploy</span><span class=\"sd\">Ship it inside an app (the app imports the <code>.pipe</code> and starts it per user), or deploy it to a server as its own project — versioned like any RocketRide artifact.</span></li>\n    <li><span class=\"st\">Schedule</span><span class=\"sd\">Deployed pipelines can run on a cron schedule with a bounded time window — \"every weekday at 08:00, run for 7 hours\" — as a shared service a whole team's apps can address.</span></li>\n  </ol>\n\n  <div class=\"callout\">\n    <strong>Embedded vs deployed — the one distinction to keep.</strong> A\n    pipeline embedded in an app runs on demand, per user, when the app starts\n    it. A pipeline deployed as its own project is a versioned server artifact:\n    it can be scheduled, shared by a whole team as one instance, and managed\n    independently of any app. The file format is identical; the lifecycle is\n    the choice.\n  </div>\n\n  <!-- ========================================================== -->\n  <!-- VOCABULARY                                                  -->\n  <!-- ========================================================== -->\n\n  <h2>Vocabulary worth keeping straight</h2>\n  <div class=\"table-scroll\">\n  <table>\n    <tr><th>Term</th><th>Means exactly</th><th>Never confuse with</th></tr>\n    <tr><td><strong>.pipe</strong></td><td>The pipeline definition file (JSON)</td><td>the running task</td></tr>\n    <tr><td><strong>task / token</strong></td><td>One running instance of a pipeline, and its handle</td><td>the definition file</td></tr>\n    <tr><td><strong>pipeline component</strong></td><td>A processing node inside a <code>.pipe</code></td><td>a UI component in an app</td></tr>\n    <tr><td><strong>lane</strong></td><td>A typed data channel between components</td><td>control connections</td></tr>\n    <tr><td><strong>control connection</strong></td><td>An invoke relationship (agent to LLM, tool, memory)</td><td>data lanes</td></tr>\n    <tr><td><strong>source</strong></td><td>A pipeline's entry point (chat, webhook, files, ...)</td><td>the client verb that drives it</td></tr>\n    <tr><td><strong>profile</strong></td><td>A named configuration preset on a component</td><td>secrets (those are <code>${ROCKETRIDE_*}</code>)</td></tr>\n    <tr><td><strong>project_id</strong></td><td>The permanent identity of a pipeline (a GUID in the file)</td><td>the task token, which is per run</td></tr>\n  </table>\n  </div>\n\n  <!-- ========================================================== -->\n  <!-- GETTING STARTED                                             -->\n  <!-- ========================================================== -->\n\n  <h2>Where to go next</h2>\n  <div class=\"grid2\">\n    <div class=\"card\">\n      <h4>Start minimal</h4>\n      <p>The best first pipeline is three components: a source, one processing\n      or model node, and a response. Get it running, then add one component at\n      a time — validation catches wiring mistakes at every step.</p>\n    </div>\n    <div class=\"card\">\n      <h4>The full guides</h4>\n      <p>The complete authoring reference lives in the workspace docs under\n      <code>.rocketride/docs/</code> — <code>ROCKETRIDE_PIPELINES.md</code>\n      for the format and patterns, <code>ROCKETRIDE_COMPONENT_REFERENCE.md</code>\n      for the catalog, and the SDK docs for driving pipelines from code.</p>\n    </div>\n  </div>\n\n  <footer>\n    RocketRide Pipelines — introduction for new users.\n  </footer>\n\n</div>\n\n</body>\n</html>\n";

